scripts.build:
bun -e 'import createApp from "@zavx0z/storybook-app"
const context = {signal: new AbortController().signal}
const result = await createApp().check({schemaVersion: 1, scope: process.cwd()}, context)
console.log(JSON.stringify(result, null, 2))
if (result.status !== "success") process.exitCode = 1'

scripts.storybook:status:
bun -e 'import createApp from "@zavx0z/storybook-app"
const context = {signal: new AbortController().signal}
const result = await createApp().status({schemaVersion: 1, includeViews: true}, context)
console.log(JSON.stringify(result, null, 2))
if (result.status !== "success") process.exitCode = 1'

scripts.storybook:attach:
bun -e 'import createApp from "@zavx0z/storybook-app"
const context = {signal: new AbortController().signal}
const result = await createApp().attach({schemaVersion: 1, root: process.argv[1] ?? process.cwd()}, context)
